import re
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger
from auto_config.generator.utils.get_bts_config import Config


class SectionSector(TextBasedSectionGeneric):
    """
    Section "sector" is a part of cus.ini config file.
    Generated content base on enb.yaml and ue.yaml.
    Example generated for CLOUD_R4A_CUS:

    [sector_1]
    enb      = 1
    antennas = 1:0:TxRx, 1:1:TxRx
    """

    def __init__(self, subsection_separator='\n\n'):
        super().__init__(subsection_separator)
        self._section_header = '[sector_{}]'

    def _prepare_section_content(self, ue_config, enb_config, *args, **kwargs):
        logger.debug("Generating Sector Section")
        cus_keys = self._get_cus_keys(ue_config)
        radio_id_map = self.get_radio_id_map(enb_config)
        mplane_only_cell_tab = self.get_mplane_only_tab(ue_config, cus_keys)
        overall_cell_id = 0

        for enb_key in enb_config.keys():
            for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                cell_params = enb_config[enb_key]['cells'][enb_cell_id]
                _, enb_id = Config.unparse_bts_key(enb_key)
                overall_cell_id += 1
                channel_dict = self._get_channel_dict(cell_params)
                antennas_list = self.get_antennas_list(channel_dict, radio_id_map, enb_id)
                for key in filter(lambda x: re.match(r'fake', x), ue_config.keys()):
                    if str(overall_cell_id) in ue_config[key]['cell']:
                        enb_id = key.split("_")[-1]
                subsection_content = [
                    self._section_header.format(str(overall_cell_id)),
                    'enb       = {}'.format(enb_id),
                    'antennas  = {}'.format(", ".join(antennas_list))
                ]
                if int(overall_cell_id) != int(enb_cell_id):
                    subsection_content.append(f"enb_cell_id = {enb_cell_id}")

                if str(overall_cell_id) in mplane_only_cell_tab:
                    subsection_content.append("mplane_only = true")

                self._section_content.append(subsection_content)

    @staticmethod
    def get_mplane_only_tab(ue_config, cus_keys):
        mplane_cell_tab = []
        for cus_key in cus_keys:
            cus_ent = ue_config[cus_key]
            mplane_cell_tab.extend(cus_ent.get('mplane_only', []))
        return mplane_cell_tab

    @staticmethod
    def get_radio_id_map(enb_config):
        overall_radio_id = 0
        radio_id_map = {}
        for enb_key in enb_config.keys():
            _, enb_id = Config.unparse_bts_key(enb_key)
            for enb_radio_id in sorted(enb_config[enb_key]['radios'].keys(), key=int):
                overall_radio_id += 1
                if enb_id in radio_id_map:
                    radio_id_map[enb_id][int(enb_radio_id)] = overall_radio_id
                else:
                    radio_id_map[enb_id] = {int(enb_radio_id): overall_radio_id}
        return radio_id_map

    @staticmethod
    def _get_channel_dict(cell_ent):
        channel_dict = {}
        for direction in cell_ent['channels']:
            port_key = direction['port']
            if port_key not in channel_dict:
                channel_dict[port_key] = {'direction': '', 'port': direction['port'],
                                          'radio': int(direction['radio'])}
            if direction['direction'] == 'TX' and 'Tx' not in channel_dict[port_key]['direction']:
                channel_dict[port_key]['direction'] += 'Tx'
            elif direction['direction'] == 'RX' and 'Rx' not in channel_dict[port_key]['direction']:
                channel_dict[port_key]['direction'] += 'Rx'
        return channel_dict

    @staticmethod
    def get_antennas_list(channel_dict, radio_id_map, enb_num):
        antennas_list = []
        for antenna in channel_dict.values():
            antenna_str = f'{radio_id_map[enb_num][int(antenna["radio"])]}:{int(antenna["port"]) - 1}:{antenna["direction"]}'
            antennas_list.append(antenna_str)
        return antennas_list

    @staticmethod
    def _add_exit_lines():
        return '\n'

    @staticmethod
    def _get_cus_keys(ue_config):
        return sorted(key for key in ue_config if re.search(r'^cus\d+$', key))
